<?php
require_once dirname(dirname(__DIR__)).'/src/bootstrap.php';Auth::requireRole('admin');$type=$_GET['type']??'summary';header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="lifelink_admin_'.$type.'_'.date('Ymd_His').'.csv"');$out=fopen('php://output','w');if($type==='security'){fputcsv($out,['Time','Severity','Event Type','User ID','Email Attempt','IP','Description']);foreach(db()->query('SELECT * FROM security_events ORDER BY created_at DESC') as $r)fputcsv($out,[$r['created_at'],$r['severity'],$r['event_type'],$r['user_id'],$r['email_attempt'],$r['ip_address'],$r['description']]);audit('admin_csv_export','security',null);}else{fputcsv($out,['Metric','Value']);$metrics=['Total users'=>"SELECT COUNT(*) FROM users",'Donors'=>"SELECT COUNT(*) FROM users WHERE role='donor'",'Active hospitals'=>"SELECT COUNT(*) FROM hospitals WHERE status='active'",'Emergency requests'=>"SELECT COUNT(*) FROM emergency_requests",'Fulfilled requests'=>"SELECT COUNT(*) FROM emergency_requests WHERE status='fulfilled'",'Campaigns'=>"SELECT COUNT(*) FROM donation_campaigns",'Transfers'=>"SELECT COUNT(*) FROM blood_transfer_requests",'Security events'=>"SELECT COUNT(*) FROM security_events"];foreach($metrics as $label=>$sql)fputcsv($out,[$label,(int)db()->query($sql)->fetchColumn()]);audit('admin_csv_export','summary',null);}fclose($out);exit;
